const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const houston = ee.Geometry.Point([-95.37, 29.76]);
  const region = houston.buffer(20000); // 20km radius around Houston

  // 2. Data Acquisition & Check
  // April 2024 - Monthly composite
  const april2024 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2024-04-01', '2024-05-01')
    .filterBounds(region);

  const aprilSize = april2024.size().getInfo();
  console.log(`April 2024 Images: ${aprilSize}`);

  if (aprilSize === 0) {
    console.log("No data for April 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // May 18, 2024 - Daily composite
  const may18 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .filterDate('2024-05-01', '2024-06-01')
    .filterBounds(region);

  const maySize = may18.size().getInfo();
  console.log(`May 2024 Images: ${maySize}`);

  if (maySize === 0) {
    console.log("No data for May 2024.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing
  const aprilImg = april2024.first().select('avg_rad');
  const mayImg = may18.first().select('avg_rad');

  // Check pixel counts
  const aprilCount = aprilImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const mayCount = mayImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`April valid pixels: ${aprilCount}`);
  console.log(`May valid pixels: ${mayCount}`);

  if (aprilCount === 0 || mayCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation
  const aprilMean = aprilImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const mayMean = mayImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`April 2024 mean radiance: ${aprilMean}`);
  console.log(`May 2024 mean radiance: ${mayMean}`);

  // 5. Validation & Final Answer
  if (aprilMean === null || mayMean === null || 
      isNaN(aprilMean) || isNaN(mayMean) ||
      aprilMean < 0 || mayMean < 0) {
    console.log("Invalid radiance values detected.");
    console.log("<answer>C3</answer>");
    return;
  }

  const decrease = mayMean < aprilMean;
  const percentChange = ((mayMean - aprilMean) / aprilMean * 100).toFixed(2);

  console.log(`Change: ${percentChange}%`);
  console.log(`Decrease detected: ${decrease}`);

  if (decrease) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
